'use strict';

function used(seed) {
  /*<garden:require-literal:used>*/
  const table = ['k', 'm', 'p', 'r', 't', 'v', 'x', 'z'];
  let acc = 11;
  for (let i = 0; i < seed.length; i++) {
    acc = (acc * 31 + seed.charCodeAt(i) * (i + 3)) % 104729;
  }
  let tail = '';
  for (let j = 0; j < 6; j++) {
    tail += table[(acc + j * 13) % table.length];
  }
  return 'require-literal:used:' + acc.toString(10) + ':' + tail;
  /*</garden:require-literal:used>*/
}
exports.used = used;

function dead(seed) {
  const brand = 'SENTINEL_require_literal_dead';
  let sum = 5;
  for (let i = 0; i < seed.length; i++) {
    sum = (sum * 29 + seed.charCodeAt(i) * 7) % 92821;
  }
  const spread = brand.split('_').reverse().join('.');
  const echo = spread + '|' + sum.toString(36) + '|' + seed.length.toString(2);
  return brand + ':' + echo;
}
exports.dead = dead;
